package dominoes

// Domino is a single stone, with the number of dots on each half.
type Domino [2]int

// MakeChain returns a way to order the given dominoes so that they form a
// correct domino chain: the dots on one half of a stone match the dots on
// the neighboring half of an adjacent stone, and the dots on the halves
// which don't have a neighbor (the first and last stone) match each other.
//
// The second return value reports whether such a chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}
	chain := make([]Domino, 0, len(input))
	if c, ok := search(input, chain, -1); ok {
		return c, true
	}
	return nil, false
}

// search builds the chain from the remaining dominoes. The next domino must
// have a half matching next, the open end of the chain. A value of -1 means
// the chain is empty and any domino may start it.
func search(remaining []Domino, chain []Domino, next int) ([]Domino, bool) {
	if len(remaining) == 0 {
		// The chain is complete; it is valid only if the open ends match.
		if chain[0][0] == chain[len(chain)-1][1] {
			return chain, true
		}
		return nil, false
	}
	for i := range remaining {
		d := remaining[i]
		rest := make([]Domino, 0, len(remaining)-1)
		rest = append(rest, remaining[:i]...)
		rest = append(rest, remaining[i+1:]...)

		if next == -1 || d[0] == next {
			if c, ok := search(rest, append(chain, d), d[1]); ok {
				return c, true
			}
		}
		// Try the reversed orientation (skip for doubles, which are
		// unchanged by reversal).
		if d[0] != d[1] && (next == -1 || d[1] == next) {
			if c, ok := search(rest, append(chain, Domino{d[1], d[0]}), d[0]); ok {
				return c, true
			}
		}
	}
	return nil, false
}

